  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = case['required_symbols']
    nodes_by_id = {n['id']: n for n in nodes}
    children = {}
    for n in nodes:
        pid = n['parent']
        if pid is not None:
            children.setdefault(pid, []).append(n['id'])
    retained = set(nodes_by_id.keys())
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    removed = []
    for n in sorted_nodes:
        nid = n['id']
        if not n['removable']:
            continue
        if nid == 'root' or n['symbol'] in required_symbols:
            continue
        child_ids = children.get(nid, [])
        if any(c in retained for c in child_ids):
            continue
        retained.remove(nid)
        removed.append(nid)
    for rsym in required_symbols:
        if not any(nodes_by_id[x]['symbol'] == rsym for x in retained):
            raise ValueError('Required symbol missing after reduction')
    retained_sorted = sorted(retained)
    return {
        'removed_node_ids': removed,
        'retained_node_ids': retained_sorted
    }"
}
